) VALUES
  ('kaak-warka', 'Kaak Warka', 'traditionnelle', NULL, NULL, 32, NULL, NULL, NULL, 12, NULL, NULL, NULL, 'L''icône tunisienne, anneau de pâte filo soufflée, amandes & fleur d''oranger.', 'Le kaak warka est l''âme de la pâtisserie tunisienne. Anneau de pâte filo finement façonné à la main, garni d''une crème d''amandes parfumée à la fleur d''oranger, et délicatement saupoudré de sucre glace.', 'À conserver à l''abri de l''humidité dans une boîte hermétique. À consommer dans les 7 jours.', NULL, NULL, 'p-kaak-warka.jpg', NULL, ARRAY['Couronne de pâte filo soufflée', 'Crème d''amandes de Sicile', 'Eau de fleur d''oranger', 'Sucre glace']::text[], ARRAY['Farine de blé', 'Amandes', 'Sucre', 'Beurre AOP', 'Œufs', 'Eau de fleur d''oranger', 'Sucre glace']::text[], ARRAY['gluten', 'lait', 'oeuf', 'fruits-coque']::text[], '{}', '{}', ARRAY['amandes', 'ramadan', 'aid']::text[], '{}', ARRAY['aid', 'mariage', 'fiancailles']::text[], '{}', '{}', 'bestseller', NULL, true, true, false, false, false, false, false, false, NULL, 10),
  ('baklawa-pistache', 'Baklawa Pistache', 'orientale', NULL, NULL, 38, NULL, NULL, NULL, 18, NULL, NULL, NULL, 'Feuilles de filo, pistaches d''Iran, sirop de fleur d''oranger.', 'Notre baklawa, c''est la rencontre entre la précision française et la générosité tunisienne. 24 fines couches de filo, abondance de pistaches d''Iran concassées, légèrement nappées d''un sirop tiède à la fleur d''oranger.', 'Conservation 10 jours en boîte hermétique.', NULL, NULL, 'p-baklawa.jpg', NULL, ARRAY['24 couches de pâte filo', 'Pistaches d''Iran', 'Sirop fleur d''oranger', 'Beurre AOP']::text[], ARRAY['Farine', 'Pistaches', 'Sucre', 'Beurre', 'Eau de fleur d''oranger', 'Citron']::text[], ARRAY['gluten', 'lait', 'fruits-coque']::text[], '{}', '{}', ARRAY['pistache', 'aid']::text[], '{}', ARRAY['aid', 'ramadan', 'mariage']::text[], '{}', '{}', 'bestseller', NULL, true, true, false, false, false, false, false, false, NULL, 20),
  ('ghraiba', 'Ghraïba', 'traditionnelle', NULL, NULL, 28, NULL, NULL, NULL, 20, NULL, NULL, NULL, 'Sablé fondant à l''amande, surmonté d''une amande entière.', 'La ghrayba se reconnaît à sa texture incomparable : un sablé qui s''effrite à peine, fondant en bouche, surmonté d''une amande entière dorée. Sans gluten.', '15 jours en boîte hermétique.', NULL, NULL, 'p-ghrayba.jpg', NULL, ARRAY['Pâte d''amandes broyées finement', 'Sucre glace', 'Amande entière']::text[], ARRAY['Amandes', 'Sucre glace', 'Blanc d''œuf']::text[], ARRAY['oeuf', 'fruits-coque']::text[], '{}', '{}', ARRAY['amandes', 'tradition']::text[], '{}', ARRAY['aid', 'ramadan']::text[], '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, false, NULL, 30),
  ('makroudh', 'Makroudh aux Dattes', 'traditionnelle', NULL, NULL, 26, NULL, NULL, NULL, 16, NULL, NULL, NULL, 'Semoule dorée, cœur de pâte de dattes, sirop léger.', 'Le makroudh raconte le sud tunisien. Semoule de blé dur travaillée à la main, cœur fondant de pâte de dattes deglet nour, frit à l''huile puis trempé dans un sirop léger au miel.', '12 jours.', NULL, NULL, 'p-makroudh.jpg', NULL, ARRAY['Semoule de blé dur', 'Pâte de dattes deglet nour', 'Sirop miel']::text[], ARRAY['Semoule', 'Dattes', 'Huile', 'Miel', 'Cannelle']::text[], ARRAY['gluten']::text[], '{}', '{}', '{}', '{}', ARRAY['aid', 'ramadan']::text[], '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, false, NULL, 40),
  ('samsa-amandes', 'Samsa aux Amandes', 'orientale', 'samsa', 'Amandes', 30, NULL, NULL, NULL, 18, NULL, NULL, NULL, 'Triangles de filo croustillants, farce aux amandes, miel.', 'Petits triangles dorés à la pâte filo, garnis d''une farce généreuse aux amandes et au miel, parfumés au géranium.', '10 jours.', NULL, NULL, 'p-samsa.jpg', NULL, ARRAY['Filo', 'Amandes mondées', 'Miel', 'Géranium']::text[], ARRAY['Farine', 'Amandes', 'Miel', 'Beurre', 'Géranium']::text[], ARRAY['gluten', 'lait', 'fruits-coque']::text[], '{}', '{}', ARRAY['amandes', 'aid']::text[], '{}', ARRAY['mariage', 'fiancailles']::text[], '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, false, NULL, 50),
  ('youyou', 'Youyou', 'traditionnelle', NULL, NULL, 24, NULL, NULL, NULL, 20, NULL, NULL, NULL, 'Petit anneau au sésame, parfait avec le thé à la menthe.', 'Anneau délicat aux graines de sésame, légèrement sucré, à la mie tendre. L''incontournable du goûter tunisien.', '8 jours.', NULL, NULL, 'p-kaak-youyou.jpg', NULL, ARRAY['Pâte levée', 'Graines de sésame']::text[], ARRAY['Farine', 'Sucre', 'Œufs', 'Beurre', 'Sésame', 'Levure']::text[], ARRAY['gluten', 'lait', 'oeuf', 'sesame']::text[], '{}', '{}', ARRAY['tradition']::text[], '{}', ARRAY['ramadan']::text[], '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, false, NULL, 60),
  ('mignardises-assortiment', 'Assortiment Pâtisseries Tunisiennes', 'petits-fours', NULL, NULL, 48, NULL, NULL, '≈ 600 g (24 pièces)', 24, NULL, NULL, NULL, 'Notre assortiment signature — un panorama de la pâtisserie tunisienne, façonné à la main.', 'Un assortiment généreux de nos icônes tunisiennes : baklawa pistache, kaak warka, samsa aux amandes, ghrayba fondante, makroudh aux dattes et kaak youyou au sésame. Présenté dans notre écrin doré, prêt à offrir ou à partager.', '10 jours à l''abri de l''humidité, dans une boîte hermétique.', 'Nos mignardises sont disponibles exclusivement dans nos coffrets et nos offres événementielles.', 'Retrait boutique Évry-Courcouronnes · Livraison Île-de-France 24-48h · Expédition France métropolitaine sous 72h (colis isotherme).', 'p-mignardises.jpg', NULL, ARRAY['24 pièces variées façonnées à la main', 'Écrin doré Ö'' Sweets', 'Livret de dégustation']::text[], ARRAY['Farine de blé', 'Amandes', 'Pistaches d''Iran', 'Beurre AOP', 'Œufs frais', 'Sucre', 'Miel', 'Eau de fleur d''oranger', 'Sésame', 'Dattes deglet nour']::text[], ARRAY['gluten', 'lait', 'oeuf', 'fruits-coque', 'sesame']::text[], '{}', ARRAY['Baklawa pistache', 'Kaak warka aux amandes', 'Samsa aux amandes & miel', 'Ghrayba fondante', 'Makroudh aux dattes', 'Kaak youyou au sésame']::text[], '{}', '{}', ARRAY['mariage', 'anniversaire', 'entreprise']::text[], '{}', '{}', 'nouveau', NULL, true, true, false, false, false, false, false, false, true, 70),
  ('bechkoutou', 'Bechkoutou', 'traditionnelle', NULL, NULL, 26, NULL, NULL, '300 g', 24, NULL, NULL, NULL, 'Biscuit tunisien traditionnel, sec et parfumé, idéal avec le thé.', 'Le Bachkoutou est un biscuit sec tunisien à la texture friable, subtilement parfumé à l''anis et au sésame. Un incontournable des goûters familiaux, servi avec un thé à la menthe.', '3 semaines en boîte hermétique.', NULL, NULL, 'p-ghrayba.jpg', NULL, ARRAY['Pâte levée maison', 'Graines de sésame', 'Anis']::text[], ARRAY['Farine', 'Sucre', 'Œufs', 'Huile', 'Sésame', 'Anis', 'Levure']::text[], ARRAY['gluten', 'oeuf', 'sesame']::text[], ARRAY['Anis', 'Sésame']::text[], '{}', ARRAY['tradition']::text[], ARRAY['mardi', 'jeudi', 'samedi']::text[], '{}', '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, false, NULL, 80),
  ('sable', 'Sablé', 'traditionnelle', NULL, NULL, 25, NULL, NULL, '350 g', 24, NULL, NULL, NULL, 'Sablé fondant beurre & vanille, coeur confiture ou pur nature.', 'Notre sablé se décline en plusieurs parfums selon la saison : nature, confiture d''abricot, coeur chocolat ou dattes. Une pâte pur beurre AOP qui fond en bouche.', '3 semaines en boîte hermétique.', NULL, NULL, 'p-ghrayba.jpg', NULL, ARRAY['Pâte sablée pur beurre', 'Cœur au choix (nature, confiture, dattes, chocolat)']::text[], ARRAY['Farine', 'Beurre AOP', 'Sucre glace', 'Œufs', 'Vanille']::text[], ARRAY['gluten', 'lait', 'oeuf']::text[], ARRAY['Nature', 'Confiture abricot', 'Dattes', 'Chocolat']::text[], '{}', ARRAY['tradition', 'ramadan', 'aid']::text[], '{}', '{}', '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, false, NULL, 90),
  ('assida-zgougou', 'Assida Zgougou', 'traditionnelle', 'assida', 'Zgougou', 14, NULL, 'le pot', '180 g', NULL, NULL, NULL, NULL, 'Crème traditionnelle de pin d''Alep, décor pignons & fruits secs.', 'L''Assida Zgougou, spécialité célébrée pour le Mouled, à base de crème de graines de pin d''Alep, sucrée et parfumée. Servie individuellement en pot.', '5 jours au frais.', NULL, NULL, 'p-mignardises.jpg', NULL, ARRAY['Crème de zgougou (pin d''Alep)', 'Décor pignons, amandes, pistaches']::text[], ARRAY['Zgougou', 'Sucre', 'Lait', 'Fécule', 'Fleur d''oranger']::text[], ARRAY['lait', 'fruits-coque']::text[], '{}', '{}', ARRAY['ramadan']::text[], '{}', '{}', '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, true, NULL, 100),
  ('bouza', 'Bouza', 'traditionnelle', NULL, NULL, 12, NULL, 'le pot', '180 g', NULL, NULL, NULL, NULL, 'Crème onctueuse à base de sorgho, lait et noisettes torréfiées.', 'La Bouza est une crème tunisienne traditionnelle du Ramadan, à base de sorgho, lait et noisettes torréfiées. Douceur réconfortante servie fraîche.', '3 jours au frais.', NULL, NULL, 'p-mignardises.jpg', NULL, ARRAY['Crème de sorgho', 'Lait entier', 'Noisettes torréfiées']::text[], ARRAY['Sorgho', 'Lait', 'Sucre', 'Noisettes']::text[], ARRAY['lait', 'fruits-coque']::text[], '{}', '{}', ARRAY['ramadan']::text[], '{}', '{}', '{}', '{}', NULL, NULL, true, true, false, false, false, false, false, true, NULL, 110),
